class Deserializer {
  public:
    Deserializer(std::vector<std::byte> const& data, Idx serialization_format)
        : deserializer_{handle_.call_with(PGM_create_deserializer_from_binary_buffer,
                                          reinterpret_cast<const char*>(data.data()), static_cast<Idx>(data.size()),
                                          serialization_format)},
          dataset_{handle_.call_with(PGM_deserializer_get_dataset, get())} {}
    Deserializer(std::vector<char> const& data, Idx serialization_format)

PGM_Serializer* PGM_create_serializer(PGM_Handle* handle, PGM_ConstDataset const* dataset,
                                      PGM_Idx serialization_format) noexcept {
    return call_with_catch(
        handle,
        [dataset, serialization_format] {
            return cast_to_c(
                create<Serializer>(safe_ptr_get(cast_to_cpp(dataset)),
                                   safe_enum<power_grid_model::SerializationFormat>(serialization_format)));
        },
        serialization_exception_handler);
}

